package net.civeira.phylax.feature.observe.observedfingerprintrule.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class GroupKeyVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property group key of observed fingerprint rule ")
  void test_group_key_v_o_builder() {
    Assertions.assertFalse(GroupKeyVO.nullValue().getGroupKey().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(GroupKeyVO.tryFrom(null).getGroupKey().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", GroupKeyVO.from("one").getGroupKey().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> GroupKeyVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", GroupKeyVO.from("one").toString());
  }
}
